-- Code generated by factory from specs/sales/list-store-sales-by-period/spec.yaml. DO NOT EDIT.

-- name: ListStoreSalesByPeriod :many
SELECT t2.sales_date, t2.amount, t2.discount, t2.closed_on
FROM (
    SELECT t1.sales_date AS sales_date, t1.amount AS amount, t1.discount AS discount, t1.closed_on AS closed_on
    FROM daily_sales AS t1
    WHERE (t1.store_code = sqlc.arg(store_code)::int4)
      AND (t1.sales_date >= sqlc.arg(date_from)::date)
      AND (t1.sales_date < sqlc.arg(date_to)::date)
) AS t2
ORDER BY t2.sales_date DESC
LIMIT 63;
